//! #99: export commands — destination picker, artifact file writes,
//! tool detection, explorer reveal and MuseScore PDF rendering.
//!
//! Self-limiting model (same posture as lib.rs's read commands): the
//! frontend cannot write anywhere it likes. A destination directory is
//! writable only when it
//!   - was picked through `export_pick_dir` this session, or
//!   - lives under the OS Documents directory.
//! File names are restricted to the export artifact extensions
//! (.musicxml/.xml/.mid/.pdf) and may not contain path separators, so
//! the command can never escape the destination directory.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use serde::{Deserialize, Serialize};
use tauri::Manager;
use tauri_plugin_dialog::DialogExt;

/// Artifact extensions the export flow may write (§17 formats).
const EXPORT_EXTENSIONS: [&str; 4] = ["musicxml", "xml", "mid", "pdf"];

/// Audio extensions the sourceAudio bundle may copy (#87).
const AUDIO_EXTENSIONS: [&str; 5] = ["wav", "mp3", "flac", "m4a", "ogg"];

/// Directories the user explicitly picked via `export_pick_dir` this
/// session — the write side of the self-limiting model.
static GRANTED_DIRS: Mutex<Option<HashSet<PathBuf>>> = Mutex::new(None);

fn grant_dir(dir: PathBuf) {
    let mut guard = GRANTED_DIRS.lock().unwrap_or_else(|e| e.into_inner());
    guard.get_or_insert_with(HashSet::new).insert(dir);
}

/// One artifact to write: file name + base64 payload (NDJSON-safe).
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportFile {
    pub name: String,
    pub data_base64: String,
}

/// `export_pick_dir`: native folder picker (Rust-side dialog plugin — no
/// JS plugin permission needed). A picked directory is granted write
/// access for the rest of the session; returns null on cancel.
#[tauri::command]
pub fn export_pick_dir(
    app: tauri::AppHandle,
    current: Option<String>,
) -> Result<Option<String>, String> {
    let mut dlg = app.dialog().file();
    if let Some(dir) = current {
        let p = PathBuf::from(&dir);
        if p.is_dir() {
            dlg = dlg.set_directory(p);
        }
    }
    let Some(path) = dlg.blocking_pick_folder() else {
        return Ok(None);
    };
    let dir = path
        .as_path()
        .map(|p| p.to_path_buf())
        .ok_or("picked path is not a filesystem path")?;
    grant_dir(dir.clone());
    Ok(Some(dir.to_string_lossy().into_owned()))
}

/// `export_default_dir`: `<Documents>/HornScribe` (reported without
/// creating — the dialog shows the path before anything is written).
#[tauri::command]
pub fn export_default_dir(app: tauri::AppHandle) -> Result<String, String> {
    let docs = app
        .path()
        .document_dir()
        .map_err(|e| format!("document dir: {e}"))?;
    let dir = docs.join("HornScribe");
    Ok(dir.to_string_lossy().into_owned())
}

/// Whether `dir` is a legal export destination: picked this session or
/// under the OS Documents directory.
fn dir_allowed(app: &tauri::AppHandle, dir: &Path) -> bool {
    if let Ok(guard) = GRANTED_DIRS.lock() {
        if let Some(set) = guard.as_ref() {
            if set.contains(dir) {
                return true;
            }
        }
    }
    if let Ok(docs) = app.path().document_dir() {
        if dir.starts_with(&docs) {
            return true;
        }
    }
    false
}

/// Validate one artifact file name: no separators, allowlisted
/// extension, non-empty stem.
fn valid_export_name(name: &str) -> bool {
    let path = Path::new(name);
    if path.file_name().and_then(|n| n.to_str()) != Some(name) {
        return false;
    }
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    EXPORT_EXTENSIONS.contains(&ext.as_str())
        && path
            .file_stem()
            .and_then(|s| s.to_str())
            .is_some_and(|s| !s.is_empty())
}

/// Like `valid_export_name` but for the audio bundle name — the
/// `<stem>_source.<ext>` copy keeps the source's own extension, which
/// is an audio type, not a score artifact type (#87).
fn valid_audio_name(name: &str) -> bool {
    let path = Path::new(name);
    if path.file_name().and_then(|n| n.to_str()) != Some(name) {
        return false;
    }
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    AUDIO_EXTENSIONS.contains(&ext.as_str())
        && path
            .file_stem()
            .and_then(|s| s.to_str())
            .is_some_and(|s| !s.is_empty())
}

/// Any name the collision check may be asked about — score artifact
/// or audio bundle copy.
fn valid_artifact_name(name: &str) -> bool {
    valid_export_name(name) || valid_audio_name(name)
}

/// `detect_tools`: probe MuseScore/ffmpeg for the export + diagnostics
/// surfaces. PATH first, then the standard MuseScore install dirs.
#[tauri::command]
pub fn detect_tools() -> DetectedTools {
    DetectedTools {
        muse_score: probe_tool(
            &["MuseScore4", "MuseScore3", "musescore"],
            &[
                r"C:\Program Files\MuseScore 4\bin\MuseScore4.exe",
                r"C:\Program Files\MuseScore 3\bin\MuseScore3.exe",
                r"C:\Program Files (x86)\MuseScore 4\bin\MuseScore4.exe",
            ],
        ),
        ffmpeg: probe_tool(&["ffmpeg"], &[]),
    }
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DetectedTools {
    pub muse_score: ToolProbe,
    pub ffmpeg: ToolProbe,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ToolProbe {
    pub status: String, // "found" | "missing"
    #[serde(skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
}

fn probe_tool(path_names: &[&str], absolute_candidates: &[&str]) -> ToolProbe {
    for name in path_names {
        if which_exists(name) {
            return ToolProbe {
                status: "found".into(),
                path: Some((*name).to_string()),
            };
        }
    }
    for candidate in absolute_candidates {
        if Path::new(candidate).is_file() {
            return ToolProbe {
                status: "found".into(),
                path: Some((*candidate).to_string()),
            };
        }
    }
    ToolProbe {
        status: "missing".into(),
        path: None,
    }
}

fn which_exists(exe: &str) -> bool {
    std::process::Command::new("where")
        .arg(exe)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

/// `reveal_in_explorer`: open a directory in the OS file manager.
#[tauri::command]
pub fn reveal_in_explorer(path: String) -> Result<(), String> {
    let p = PathBuf::from(&path);
    if !p.is_dir() {
        return Err(format!("not a directory: {path}"));
    }
    std::process::Command::new("explorer")
        .arg(&p)
        .spawn()
        .map_err(|e| format!("explorer {}: {e}", p.display()))?;
    Ok(())
}

/// `project_save_path`: native save-file picker for `.hornscribe.json`
/// (#100). The picked file's parent directory is granted write access
/// (same model as `export_pick_dir`); returns null on cancel.
#[tauri::command]
pub fn project_save_path(
    app: tauri::AppHandle,
    suggested_name: Option<String>,
) -> Result<Option<String>, String> {
    let mut dlg = app
        .dialog()
        .file()
        .add_filter("HornScribe プロジェクト", &["hornscribe.json"]);
    if let Some(name) = suggested_name {
        if !name.is_empty() {
            dlg = dlg.set_file_name(&name);
        }
    }
    let Some(path) = dlg.blocking_save_file() else {
        return Ok(None);
    };
    let file = path
        .as_path()
        .map(|p| p.to_path_buf())
        .ok_or("picked path is not a filesystem path")?;
    if let Some(parent) = file.parent() {
        grant_dir(parent.to_path_buf());
    }
    // The dialog may return the name without the suffix the filter
    // describes — append it so the worker's path check never trips
    // on a user-typed name.
    let file = if file.to_string_lossy().ends_with(".hornscribe.json") {
        file
    } else {
        let mut name = file
            .file_name()
            .unwrap_or_default()
            .to_string_lossy()
            .into_owned();
        // "take.json" → "take"; "take.hornscribe" → "take"
        for suffix in [".hornscribe.json", ".hornscribe", ".json"] {
            if let Some(stripped) = name.strip_suffix(suffix) {
                name = stripped.to_string();
                break;
            }
        }
        file.with_file_name(format!("{name}.hornscribe.json"))
    };
    Ok(Some(file.to_string_lossy().into_owned()))
}

/// Which of the requested artifact names already exist in `dir` —
/// the collision check the dialog runs before writing so an export
/// never silently destroys a previous result (#231). Returns the
/// clashing *names* (not paths); an empty list means the set is clear.
#[tauri::command]
pub fn export_check_existing(
    app: tauri::AppHandle,
    dir: String,
    names: Vec<String>,
) -> Result<Vec<String>, String> {
    let dir_path = PathBuf::from(&dir);
    if !dir_allowed(&app, &dir_path) {
        return Err("PERMISSION_DENIED".to_string());
    }
    let mut existing = Vec::new();
    for name in names {
        if !valid_artifact_name(&name) {
            return Err(format!("invalid export name: {}", name));
        }
        if dir_path.join(&name).is_file() {
            existing.push(name);
        }
    }
    Ok(existing)
}

/// One source-audio copy for `export_run` (#87): the final artifact
/// name plus the absolute path of the audio file to copy.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportAudioCopy {
    pub name: String,
    pub src: String,
}

/// One PDF artifact for `export_run`: the final .pdf name plus the
/// MusicXML source rendered through MuseScore.
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ExportRunPdf {
    pub name: String,
    pub music_xml: String,
}

/// `export_run` — the transactional export (#258). Every artifact is
/// produced into a private staging directory first; only when audio,
/// batch files AND all PDF renders succeed does the command move them
/// into the destination. A failure anywhere cleans the staging dir and
/// leaves the destination untouched — no half-written artifact sets.
///
/// Collision policy (#231) is decided by the frontend before this call
/// (export_check_existing + the dialog's overwrite/rename/cancel), so a
/// commit here overwrites intentionally.
#[tauri::command]
pub fn export_run(
    app: tauri::AppHandle,
    dir: String,
    audio: Option<ExportAudioCopy>,
    files: Vec<ExportFile>,
    pdfs: Vec<ExportRunPdf>,
    musescore_path: Option<String>,
) -> Result<Vec<String>, String> {
    let dir_path = PathBuf::from(&dir);
    if !dir_allowed(&app, &dir_path) {
        return Err("PERMISSION_DENIED".to_string());
    }
    run_export(&dir_path, audio, files, pdfs, musescore_path)
}

/// The transactional body of `export_run`, split from the AppHandle
/// wrapper so the stage→commit flow is unit-testable (#258).
fn run_export(
    dir_path: &Path,
    audio: Option<ExportAudioCopy>,
    files: Vec<ExportFile>,
    pdfs: Vec<ExportRunPdf>,
    musescore_path: Option<String>,
) -> Result<Vec<String>, String> {
    // Validate everything before touching the filesystem — a bad name
    // must not leave a half-staged directory behind.
    for f in &files {
        if !valid_export_name(&f.name) {
            return Err(format!("invalid export name: {}", f.name));
        }
    }
    for p in &pdfs {
        if !valid_export_name(&p.name) || !p.name.to_ascii_lowercase().ends_with(".pdf") {
            return Err(format!("invalid export name: {}", p.name));
        }
    }
    if let Some(a) = &audio {
        if !valid_audio_name(&a.name) {
            return Err(format!("invalid export name: {}", a.name));
        }
        if !PathBuf::from(&a.src).is_file() {
            return Err(format!("source audio not found: {}", a.src));
        }
    }
    let exe = if pdfs.is_empty() {
        None
    } else {
        let path = musescore_path.ok_or("MUSESCORE_UNAVAILABLE")?;
        let exe = PathBuf::from(&path);
        if !exe.is_file() {
            return Err("MUSESCORE_UNAVAILABLE".to_string());
        }
        Some(exe)
    };
    std::fs::create_dir_all(dir_path).map_err(|e| format!("create {}: {e}", dir_path.display()))?;

    let uniq = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);
    let staging =
        std::env::temp_dir().join(format!("hornscribe-export-{}-{}", std::process::id(), uniq));
    let result = (|| -> Result<Vec<String>, String> {
        std::fs::create_dir_all(&staging)
            .map_err(|e| format!("stage {}: {e}", staging.display()))?;
        let mut staged: Vec<(PathBuf, PathBuf)> = Vec::new();
        if let Some(a) = &audio {
            let src = PathBuf::from(&a.src);
            let tmp = staging.join(&a.name);
            std::fs::copy(&src, &tmp).map_err(|e| format!("copy {}: {e}", tmp.display()))?;
            staged.push((tmp, dir_path.join(&a.name)));
        }
        for f in &files {
            let bytes = decode_base64(&f.data_base64).map_err(|e| format!("{}: {e}", f.name))?;
            let tmp = staging.join(&f.name);
            std::fs::write(&tmp, &bytes).map_err(|e| format!("write {}: {e}", tmp.display()))?;
            staged.push((tmp, dir_path.join(&f.name)));
        }
        if let Some(exe) = &exe {
            for p in &pdfs {
                let tmp_xml = staging.join(format!("{}.musicxml", p.name));
                std::fs::write(&tmp_xml, p.music_xml.as_bytes())
                    .map_err(|e| format!("stage {}: {e}", tmp_xml.display()))?;
                let tmp_pdf = staging.join(&p.name);
                let status = std::process::Command::new(exe)
                    .args(["-o"])
                    .arg(&tmp_pdf)
                    .arg(&tmp_xml)
                    .stdout(std::process::Stdio::null())
                    .stderr(std::process::Stdio::null())
                    .status();
                let _ = std::fs::remove_file(&tmp_xml);
                match status {
                    Ok(s) if s.success() && tmp_pdf.is_file() => {}
                    Ok(s) => {
                        return Err(format!("MuseScore exited with {s}"));
                    }
                    Err(e) => {
                        return Err(format!("spawn {}: {e}", exe.display()));
                    }
                }
                staged.push((tmp_pdf, dir_path.join(&p.name)));
            }
        }
        let mut out = Vec::with_capacity(staged.len());
        for (tmp, dest) in staged {
            if dest.exists() {
                let _ = std::fs::remove_file(&dest);
            }
            match std::fs::rename(&tmp, &dest) {
                Ok(()) => {}
                Err(_) => {
                    std::fs::copy(&tmp, &dest)
                        .map_err(|e| format!("write {}: {e}", dest.display()))?;
                    let _ = std::fs::remove_file(&tmp);
                }
            }
            out.push(dest.to_string_lossy().into_owned());
        }
        Ok(out)
    })();
    let _ = std::fs::remove_dir_all(&staging);
    result
}

/// `open_in_musescore`: stage the score as a temp MusicXML and launch the
/// MuseScore GUI on it (spec 13: 高度編集 → MuseScoreで開く). Unlike
/// `export_run`'s staged PDF renders, the process is not awaited —
/// the user keeps working in MuseScore — so the staged file is left
/// for the OS temp cleaner.
/// A millisecond suffix keeps successive opens (edited score re-opens)
/// from overwriting a file the GUI may still hold.
#[tauri::command]
pub fn open_in_musescore(
    musescore_path: String,
    music_xml: String,
    basename: String,
) -> Result<String, String> {
    let exe = PathBuf::from(&musescore_path);
    if !exe.is_file() {
        return Err("MUSESCORE_UNAVAILABLE".to_string());
    }
    let stem_raw: String = basename
        .chars()
        .map(|c| {
            if c.is_alphanumeric() || c == '-' || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect();
    let stem: &str = if stem_raw.is_empty() {
        "score"
    } else {
        &stem_raw
    };
    let millis = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);
    let staging =
        std::env::temp_dir().join(format!("hornscribe-open-{}-{}.musicxml", stem, millis));
    std::fs::write(&staging, music_xml.as_bytes())
        .map_err(|e| format!("stage {}: {e}", staging.display()))?;
    std::process::Command::new(&exe)
        .arg(&staging)
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn()
        .map_err(|e| format!("spawn {}: {e}", exe.display()))?;
    Ok(staging.to_string_lossy().into_owned())
}

/// Minimal RFC 4648 decoder — avoids a base64 dependency for a
/// few-hundred-KB worst-case payload.
fn decode_base64(input: &str) -> Result<Vec<u8>, String> {
    fn val(b: u8) -> Result<u8, String> {
        match b {
            b'A'..=b'Z' => Ok(b - b'A'),
            b'a'..=b'z' => Ok(b - b'a' + 26),
            b'0'..=b'9' => Ok(b - b'0' + 52),
            b'+' => Ok(62),
            b'/' => Ok(63),
            _ => Err(format!("bad base64 byte {b}")),
        }
    }
    let bytes: Vec<u8> = input.bytes().filter(|b| !b.is_ascii_whitespace()).collect();
    if bytes.len() % 4 != 0 {
        return Err("base64 length not a multiple of 4".into());
    }
    let mut out = Vec::with_capacity(bytes.len() / 4 * 3);
    for chunk in bytes.chunks(4) {
        let pad = chunk.iter().rev().take_while(|&&b| b == b'=').count();
        if pad > 2 {
            return Err("too much base64 padding".into());
        }
        let mut acc: u32 = 0;
        for (i, &b) in chunk.iter().enumerate() {
            let v = if b == b'=' { 0 } else { val(b)? };
            acc |= (v as u32) << (18 - i * 6);
        }
        out.push((acc >> 16) as u8);
        if pad < 2 {
            out.push((acc >> 8) as u8);
        }
        if pad < 1 {
            out.push(acc as u8);
        }
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tmp_dir(tag: &str) -> PathBuf {
        let uniq = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        std::env::temp_dir().join(format!(
            "hornscribe-export-test-{}-{}-{}",
            std::process::id(),
            uniq,
            tag
        ))
    }

    fn b64(s: &str) -> String {
        // Minimal encoder for test payloads (decode_base64 inverse).
        const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        let bytes = s.as_bytes();
        let mut out = String::new();
        for chunk in bytes.chunks(3) {
            let b = [
                chunk[0],
                *chunk.get(1).unwrap_or(&0),
                *chunk.get(2).unwrap_or(&0),
            ];
            let n = ((b[0] as u32) << 16) | ((b[1] as u32) << 8) | b[2] as u32;
            out.push(T[(n >> 18) as usize & 63] as char);
            out.push(T[(n >> 12) as usize & 63] as char);
            out.push(if chunk.len() > 1 {
                T[(n >> 6) as usize & 63] as char
            } else {
                '='
            });
            out.push(if chunk.len() > 2 {
                T[n as usize & 63] as char
            } else {
                '='
            });
        }
        out
    }

    fn file(name: &str, body: &str) -> ExportFile {
        ExportFile {
            name: name.to_string(),
            data_base64: b64(body),
        }
    }

    #[test]
    fn export_names_are_validated() {
        assert!(valid_export_name("take_concert.musicxml"));
        assert!(valid_export_name("take_playback.mid"));
        assert!(!valid_export_name("take_source.wav"));
        assert!(!valid_export_name("../evil.musicxml"));
        assert!(!valid_export_name("a/b.pdf"));
        assert!(valid_audio_name("take_source.wav"));
        assert!(!valid_audio_name("take_concert.musicxml"));
        assert!(valid_artifact_name("take_source.mp3"));
        assert!(valid_artifact_name("take_horn_in_f.pdf"));
    }

    #[test]
    fn run_export_commits_all_artifacts() {
        let dir = tmp_dir("commit");
        let src = tmp_dir("commit-src");
        std::fs::create_dir_all(&src).unwrap();
        let audio = src.join("take.wav");
        std::fs::write(&audio, b"RIFF").unwrap();
        let out = run_export(
            &dir,
            Some(ExportAudioCopy {
                name: "take_source.wav".into(),
                src: audio.to_string_lossy().into_owned(),
            }),
            vec![
                file("take_concert.musicxml", "<xml/>"),
                file("take_playback.mid", "MThd"),
            ],
            vec![],
            None,
        )
        .unwrap();
        assert_eq!(out.len(), 3);
        assert_eq!(
            std::fs::read(dir.join("take_concert.musicxml")).unwrap(),
            b"<xml/>"
        );
        assert_eq!(std::fs::read(dir.join("take_source.wav")).unwrap(), b"RIFF");
        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&src);
    }

    #[test]
    fn run_export_failure_leaves_destination_untouched() {
        // #258: a mid-batch failure must not leave the first artifact
        // behind — staging is cleaned and nothing reaches the dest.
        let dir = tmp_dir("atomic");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("keep.txt"), b"old").unwrap();
        let err = run_export(
            &dir,
            None,
            vec![
                file("take_concert.musicxml", "<xml/>"),
                ExportFile {
                    name: "take_playback.mid".into(),
                    data_base64: "!!!bad".into(),
                },
            ],
            vec![],
            None,
        )
        .unwrap_err();
        assert!(err.contains("take_playback.mid"));
        assert!(!dir.join("take_concert.musicxml").exists());
        assert!(!dir.join("take_playback.mid").exists());
        assert_eq!(std::fs::read(dir.join("keep.txt")).unwrap(), b"old");
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn run_export_pdf_without_musescore_fails_before_writes() {
        let dir = tmp_dir("pdf");
        let err = run_export(
            &dir,
            None,
            vec![file("take_concert.musicxml", "<xml/>")],
            vec![ExportRunPdf {
                name: "take_concert.pdf".into(),
                music_xml: "<xml/>".into(),
            }],
            None,
        )
        .unwrap_err();
        assert_eq!(err, "MUSESCORE_UNAVAILABLE");
        assert!(!dir.join("take_concert.musicxml").exists());
        let _ = std::fs::remove_dir_all(&dir);
    }
}

//! HornScribe desktop shell — UI-001 spike + UI-020 import plumbing.
//!
//! Security model: no fs/asset-protocol/shell/http grants. The only plugin
//! is `tauri-plugin-dialog`, capability-scoped to `dialog:allow-open` so the
//! frontend can show the native picker (no save/message variants granted).
//!
//! Because the ACL does not govern app-defined commands, the file-reading
//! commands below self-limit instead of relying on a permission grant:
//! `read_audio_bytes` serves only the advertised audio extensions with a
//! hard size cap, and `read_project_file` serves only `*.hornscribe.json`
//! project documents. Both are read-only — the source file is never
//! modified (GUI_UX_SPEC §3 / FND-001 SourceAudioRef).

use serde::Serialize;

mod capture;
mod engine;
mod export;

/// Audio containers the import UX advertises (GUI_UX_SPEC §3 formats line).
/// The frontend rejects other extensions before reaching this command; the
/// allowlist here is the Rust-side backstop so the command cannot be turned
/// into a general file reader.
const AUDIO_EXTENSIONS: [&str; 5] = ["wav", "mp3", "flac", "m4a", "ogg"];

/// HornScribe project document suffix (python/hornscribe/project/model.py).
const PROJECT_FILE_SUFFIX: &str = ".hornscribe.json";

/// 512 MiB — far above any realistic horn recording (~90 MB for 10 min of
/// PCM16 stereo 44.1 kHz); guards against unbounded reads.
const MAX_AUDIO_BYTES: u64 = 512 * 1024 * 1024;
/// Project JSON embeds the canonical score + both MusicXML bodies
/// (#218), so long pieces legitimately exceed the old 16 MiB cap —
/// the save side has no limit and the open side must not reject
/// projects it wrote (#262). 128 MiB is far above any realistic
/// score while still guarding against unbounded reads.
const MAX_PROJECT_BYTES: u64 = 128 * 1024 * 1024;

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct ShellInfo {
    app_name: String,
    version: String,
    rust_target_env: String,
}

#[tauri::command]
fn shell_info(app: tauri::AppHandle) -> ShellInfo {
    let pkg = app.package_info();
    ShellInfo {
        app_name: pkg.name.clone(),
        version: pkg.version.to_string(),
        rust_target_env: (if cfg!(target_env = "msvc") {
            "msvc"
        } else if cfg!(target_env = "gnu") {
            "gnu"
        } else {
            "other"
        })
        .to_string(),
    }
}

/// Read a user-selected audio file and return its bytes over raw IPC so the
/// webview can decode it (WebAudio `decodeAudioData`) and hash it
/// (WebCrypto SHA-256, mirroring `hash_file_sha256` in the project schema).
/// Read-only, extension-allowlisted, size-capped.
#[tauri::command]
fn read_audio_bytes(path: String) -> Result<tauri::ipc::Response, String> {
    let ext = std::path::Path::new(&path)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_ascii_lowercase();
    if !AUDIO_EXTENSIONS.contains(&ext.as_str()) {
        return Err(format!("unsupported audio extension: {ext}"));
    }
    let meta = std::fs::metadata(&path).map_err(|e| format!("{path}: {e}"))?;
    if !meta.is_file() {
        return Err(format!("not a file: {path}"));
    }
    if meta.len() > MAX_AUDIO_BYTES {
        return Err(format!("audio file too large: {} bytes", meta.len()));
    }
    let bytes = std::fs::read(&path).map_err(|e| format!("{path}: {e}"))?;
    Ok(tauri::ipc::Response::new(bytes))
}

/// Read a `*.hornscribe.json` project document (schema v1, FND-001) so the
/// import flow can recover sourceAudio.originalPath/contentHash for the
/// relink UX. Read-only, suffix-restricted, size-capped.
#[tauri::command]
fn read_project_file(path: String) -> Result<tauri::ipc::Response, String> {
    if !path.to_ascii_lowercase().ends_with(PROJECT_FILE_SUFFIX) {
        return Err(format!("not a HornScribe project file: {path}"));
    }
    let meta = std::fs::metadata(&path).map_err(|e| format!("{path}: {e}"))?;
    if !meta.is_file() {
        return Err(format!("not a file: {path}"));
    }
    if meta.len() > MAX_PROJECT_BYTES {
        return Err(format!("project file too large: {} bytes", meta.len()));
    }
    let bytes = std::fs::read(&path).map_err(|e| format!("{path}: {e}"))?;
    Ok(tauri::ipc::Response::new(bytes))
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .invoke_handler(tauri::generate_handler![
            shell_info,
            read_audio_bytes,
            read_project_file,
            capture::capture_start,
            capture::capture_stop,
            capture::capture_cancel,
            capture::capture_status,
            capture::capture_devices,
            capture::capture_pause,
            capture::capture_resume,
            capture::recordings_info,
            capture::open_recordings_dir,
            capture::clear_recordings,
            capture::recordings_list,
            capture::delete_recording,
            capture::copy_recording_to_managed,
            capture::sources_info,
            capture::sources_list,
            capture::open_sources_dir,
            capture::delete_source,
            engine::engine_spawn,
            engine::engine_write,
            engine::engine_close_stdin,
            engine::engine_kill,
            export::export_pick_dir,
            export::export_default_dir,
            export::export_check_existing,
            export::export_run,
            export::detect_tools,
            export::reveal_in_explorer,
            export::project_save_path,
            export::open_in_musescore,
        ])
        .build(tauri::generate_context!())
        .expect("error while building HornScribe shell")
        .run(|_app, event| {
            if let tauri::RunEvent::Exit = event {
                engine::kill_engine_on_exit();
            }
        });
}

import { useCallback, useEffect, useRef, useState } from "react";
import { Checkbox, Tooltip } from "@fluentui/react-components";
import {
  CheckmarkCircle24Regular,
  ErrorCircle24Regular,
  Warning24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsDialog } from "../components/primitives/Dialog";
import { HsProgress } from "../components/primitives/Progress";
import type { ToolPathOverrides } from "../diagnostics/types";
import type { ExportPort } from "./port";
import {
  exportErrorCode,
  pdfBlocked,
  EXPORT_FORMAT_GROUPS,
  type ExportCapabilities,
  type ExportFormatId,
  type ExportResult,
} from "./types";

type Phase = "loading" | "form" | "running" | "collision" | "done" | "error";
type ErrorKind = "permission" | "unavailable" | "musescore" | "failed";

const ERROR_TITLE: Record<ErrorKind, string> = {
  permission: ja.errors.exportPermissionDenied.title,
  unavailable: ja.errors.engineUnavailable.title,
  musescore: ja.errors.musescoreMissing.title,
  failed: ja.errors.exportFailed.title,
};

const ERROR_BODY: Record<ErrorKind, string> = {
  permission: ja.errors.exportPermissionDenied.body,
  unavailable: ja.errors.engineUnavailable.body,
  musescore: ja.errors.musescoreMissing.body,
  failed: ja.errors.exportFailed.body,
};

/**
 * 書き出し dialog (GUI_UX_SPEC §17, §20; issue UI-060).
 *
 * Formats (all checked by default):
 *   楽譜: コンサートピッチ / F管ホルン MusicXML
 *   PDF:  コンサートピッチ / F管ホルン PDF  — disabled when MuseScore is
 *         missing, with the spec'd note + 場所を指定 recovery; MusicXML and
 *         MIDI stay available (acceptance: "missing MuseScore does not
 *         block other formats").
 *   MIDI: 再生用MIDI（実音） — sounding pitch only (ENG-001).
 *
 * Phases: loading → form → running → done | error. Errors keep the §20
 * shape (何が失敗したか → 影響 → 次にできること) and never render engine
 * output — only stable ExportError codes map to Japanese recovery copy.
 */
export function ExportDialog({
  open,
  onOpenChange,
  port,
  defaultDestination,
  toolOverrides,
  onOpenSettings,
  onOpenDiagnostics,
  onAnnounce,
}: {
  open: boolean;
  onOpenChange(open: boolean): void;
  port: ExportPort;
  /** 設定 → 書き出し → 既定の保存先 ("" = ask the port). */
  defaultDestination: string;
  /** 設定 → ツール user paths — non-empty paths override probing. */
  toolOverrides?: ToolPathOverrides;
  /** Recovery: opens 設定 focused on the 書き出し category. */
  onOpenSettings(category: "export"): void;
  onOpenDiagnostics(): void;
  onAnnounce(message: string): void;
}) {
  const [phase, setPhase] = useState<Phase>("loading");
  const [caps, setCaps] = useState<ExportCapabilities | null>(null);
  const [destination, setDestination] = useState("");
  const [selected, setSelected] = useState<Record<ExportFormatId, boolean>>({
    concertMusicxml: true,
    hornMusicxml: true,
    concertPdf: true,
    hornPdf: true,
    playbackMidi: true,
    sourceAudio: true,
  });
  const [result, setResult] = useState<ExportResult | null>(null);
  const [errorKind, setErrorKind] = useState<ErrorKind>("failed");
  // #231: pending collision prompt — the port's onCollision awaits
  // this resolver while the dialog shows overwrite/rename/cancel.
  const [collision, setCollision] = useState<{
    names: readonly string[];
    resolve: (policy: "overwrite" | "rename" | "cancel") => void;
  } | null>(null);
  // Stale-response guard: a probe/export finishing after close or a newer
  // attempt must not overwrite the current phase.
  const generation = useRef(0);

  const e = ja.exportSheet;
  const errs = ja.errors;

  // Probe capabilities + destination when the dialog opens.
  useEffect(() => {
    if (!open) return;
    const gen = ++generation.current;
    setPhase("loading");
    setCaps(null);
    setResult(null);
    setSelected({
      concertMusicxml: true,
      hornMusicxml: true,
      concertPdf: true,
      hornPdf: true,
      playbackMidi: true,
      sourceAudio: true,
    });
    let cancelled = false;
    void (async () => {
      try {
        const [capabilities, fallbackDir] = await Promise.all([
          port.capabilities(toolOverrides),
          defaultDestination
            ? Promise.resolve(defaultDestination)
            : port.defaultDestination(),
        ]);
        if (cancelled || generation.current !== gen) return;
        setCaps(capabilities);
        setDestination(defaultDestination || fallbackDir);
        setPhase("form");
      } catch (err) {
        if (cancelled || generation.current !== gen) return;
        setErrorKind(
          exportErrorCode(err) === "ENGINE_UNAVAILABLE"
            ? "unavailable"
            : "failed",
        );
        setPhase("error");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [open, port, defaultDestination, toolOverrides]);

  const close = useCallback(() => {
    generation.current += 1;
    // #231: a pending collision prompt must not keep the export
    // promise alive past close — resolve it as cancelled.
    collision?.resolve("cancel");
    setCollision(null);
    onOpenChange(false);
  }, [onOpenChange, collision]);

  // #231: the collision prompt's three policies — overwrite keeps
  // the planned names, rename re-stems the set to <basename>_N,
  // cancel aborts (the port surfaces EXPORT_CANCELLED → form).
  const resolveCollision = useCallback(
    (policy: "overwrite" | "rename" | "cancel") => {
      const pending = collision;
      setCollision(null);
      if (policy === "cancel") {
        pending?.resolve("cancel");
        return;
      }
      setPhase("running");
      pending?.resolve(policy);
    },
    [collision],
  );

  const blocked = caps ? pdfBlocked(caps) : false;
  // #87: the audio bundle needs a real path — browser-held bytes and
  // pathless recordings keep the checkbox off with an honest tooltip.
  const audioBlocked = caps != null && !caps.audioAvailable;
  const running = phase === "running";
  // Formats that will actually export — checked AND not blocked.
  // anyChecked alone let submit run with an empty list when every
  // checked format was blocked (e.g. PDF-only selection + no MuseScore).
  const effectiveFormats = (
    Object.keys(selected) as ExportFormatId[]
  ).filter(
    (f) =>
      selected[f] &&
      !(blocked && EXPORT_FORMAT_GROUPS[f] === "pdf") &&
      !(audioBlocked && f === "sourceAudio"),
  );

  const submit = useCallback(async () => {
    const gen = ++generation.current;
    setPhase("running");
    try {
      const res = await port.export({
        formats: effectiveFormats,
        destination,
        // #231: existing artifact names pause the export here — the
        // dialog shows one prompt for the whole set and the chosen
        // policy resumes (or cancels) the transactional write.
        onCollision: (names) =>
          new Promise<"overwrite" | "rename" | "cancel">((resolve) => {
            if (generation.current !== gen) {
              resolve("cancel");
              return;
            }
            setCollision({ names, resolve });
            setPhase("collision");
          }),
      });
      if (generation.current !== gen) return;
      setResult(res);
      setPhase("done");
      onAnnounce(ja.notifications.exportDone);
    } catch (err) {
      if (generation.current !== gen) return;
      const code = exportErrorCode(err);
      if (code === "EXPORT_CANCELLED") {
        // #231: the user cancelled at the collision prompt — back to
        // the form quietly, not an error surface.
        setPhase("form");
        return;
      }
      setErrorKind(
        code === "PERMISSION_DENIED"
          ? "permission"
          : code === "ENGINE_UNAVAILABLE"
            ? "unavailable"
            : code === "MUSESCORE_UNAVAILABLE"
              ? "musescore"
              : "failed",
      );
      setPhase("error");
    }
  }, [effectiveFormats, port, destination, onAnnounce]);

  const pickDestination = useCallback(async () => {
    try {
      const dir = await port.chooseDestination(destination);
      if (dir) setDestination(dir);
    } catch {
      /* unsupported picker — the path row stays editable nowhere else,
         so surface the honest failure instead of dying silently */
      onAnnounce(ja.exportSheet.destinationPickFailed);
    }
  }, [port, destination, onAnnounce]);

  const reveal = useCallback(async () => {
    const dir = result?.destination ?? destination;
    const ok = await port.revealInExplorer(dir).catch(() => false);
    if (!ok) onAnnounce(ja.exportSheet.revealFailed);
  }, [port, result, destination, onAnnounce]);

  const goToMuseScoreSettings = useCallback(() => {
    close();
    onOpenSettings("export");
  }, [close, onOpenSettings]);

  const toggle =
    (key: ExportFormatId) =>
    (_: unknown, d: { checked: boolean | "mixed" }) =>
      setSelected((s) => ({ ...s, [key]: d.checked === true }));

  const title =
    phase === "done"
      ? e.completeTitle
      : phase === "error"
        ? ERROR_TITLE[errorKind]
        : phase === "collision"
          ? e.collisionTitle
        : e.title;

  const formatRow = (id: ExportFormatId) => {
    const pdfOff = blocked && EXPORT_FORMAT_GROUPS[id] === "pdf";
    const audioOff = audioBlocked && id === "sourceAudio";
    const disabled = running || pdfOff || audioOff;
    const checkbox = (
      <Checkbox
        checked={selected[id]}
        onChange={toggle(id)}
        label={e.options[id]}
        disabled={disabled}
      />
    );
    // Disabled checkboxes can't announce *why* — the spec'd tooltip does.
    if (audioOff) {
      return (
        <Tooltip
          key={id}
          content={e.audioDisabledTooltip}
          relationship="label"
        >
          <span className="hs-export__option">{checkbox}</span>
        </Tooltip>
      );
    }
    return pdfOff ? (
      <Tooltip
        key={id}
        content={e.pdfDisabledTooltip}
        relationship="label"
      >
        <span className="hs-export__option">{checkbox}</span>
      </Tooltip>
    ) : (
      <span key={id} className="hs-export__option">
        {checkbox}
      </span>
    );
  };

  return (
    <HsDialog
      open={open}
      onOpenChange={(o) => (o ? onOpenChange(true) : close())}
      title={title}
      actions={
        phase === "form" || running ? (
          <>
            <HsButton onClick={close}>{ja.common.cancel}</HsButton>
            <HsButton
              variant="primary"
              disabled={effectiveFormats.length === 0 || running || !destination}
              loading={running}
              onClick={() => void submit()}
            >
              {running ? e.running : e.submit}
            </HsButton>
          </>
        ) : phase === "collision" ? (
          <>
            <HsButton onClick={() => resolveCollision("cancel")}>
              {ja.common.cancel}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => resolveCollision("rename")}
            >
              {e.collisionRename}
            </HsButton>
            <HsButton
              variant="primary"
              onClick={() => resolveCollision("overwrite")}
            >
              {e.collisionOverwrite}
            </HsButton>
          </>
        ) : phase === "done" ? (
          <>
            <HsButton onClick={() => void reveal()}>
              {e.revealInExplorer}
            </HsButton>
            <HsButton variant="primary" onClick={close}>
              {ja.common.close}
            </HsButton>
          </>
        ) : phase === "error" ? (
          <>
            {errorKind === "permission" || errorKind === "failed" ? (
              <HsButton onClick={() => setPhase("form")}>
                {errs.exportPermissionDenied.actions.chooseDestination}
              </HsButton>
            ) : null}
            {errorKind === "failed" ? (
              <HsButton onClick={() => void submit()}>
                {errs.exportFailed.actions.retry}
              </HsButton>
            ) : null}
            {errorKind === "musescore" ? (
              <HsButton
                variant="primary"
                onClick={goToMuseScoreSettings}
              >
                {errs.musescoreMissing.actions.specifyMusescore}
              </HsButton>
            ) : null}
            {errorKind === "unavailable" ? (
              <HsButton
                variant="primary"
                onClick={() => {
                  close();
                  onOpenDiagnostics();
                }}
              >
                {errs.engineUnavailable.actions.diagnostics}
              </HsButton>
            ) : null}
            <HsButton onClick={close}>{ja.common.close}</HsButton>
          </>
        ) : undefined
      }
    >
      {phase === "loading" ? (
        <HsProgress label={e.loading} />
      ) : phase === "form" || running ? (
        <div className="hs-export">
          <h3 className="hs-export__section">{e.scoreSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertMusicxml")}
            {formatRow("hornMusicxml")}
          </div>

          <h3 className="hs-export__section">{e.pdfSection}</h3>
          <div className="hs-export__group">
            {formatRow("concertPdf")}
            {formatRow("hornPdf")}
          </div>
          {blocked ? (
            <p className="hs-export__note" role="note">
              <Warning24Regular aria-hidden="true" />
              <span>{e.museScoreMissingNote}</span>
              <HsButton
                variant="subtle"
                size="small"
                onClick={goToMuseScoreSettings}
              >
                {e.specifyMuseScore}
              </HsButton>
            </p>
          ) : null}

          <h3 className="hs-export__section">{e.midiSection}</h3>
          <div className="hs-export__group">{formatRow("playbackMidi")}</div>

          <h3 className="hs-export__section">{e.audioSection}</h3>
          <div className="hs-export__group">{formatRow("sourceAudio")}</div>

          <div className="hs-export__dest">
            <span className="hs-export__dest-label">{e.destination}</span>
            <span className="hs-export__dest-path" title={destination}>
              {destination}
            </span>
            <HsButton
              variant="secondary"
              size="small"
              disabled={running}
              onClick={() => void pickDestination()}
            >
              {ja.common.browse}
            </HsButton>
          </div>

          {running ? (
            <HsProgress label={e.running} className="hs-export__progress" />
          ) : null}
        </div>
      ) : phase === "collision" ? (
        <div className="hs-export">
          <p className="hs-export__error">
            <Warning24Regular
              aria-hidden="true"
              className="hs-export__error-icon"
            />
            <span>{e.collisionBody}</span>
          </p>
          <ul className="hs-export__files">
            {collision?.names.map((n) => <li key={n}>{n}</li>)}
          </ul>
        </div>
      ) : phase === "done" ? (
        <div className="hs-export">
          <p className="hs-export__done">
            <CheckmarkCircle24Regular
              aria-hidden="true"
              className="hs-export__done-icon"
            />
            <span>
              {e.completeCount.replace(
                "{count}",
                String(result?.files.length ?? 0),
              )}
            </span>
          </p>
          <ul className="hs-export__files">
            {result?.files.map((f) => (
              <li key={f.format} title={f.path}>
                {f.name}
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <div className="hs-export">
          <p className="hs-export__error">
            <ErrorCircle24Regular
              aria-hidden="true"
              className="hs-export__error-icon"
            />
            <span>{ERROR_BODY[errorKind]}</span>
          </p>
        </div>
      )}
    </HsDialog>
  );
}

// @vitest-environment jsdom
/**
 * TauriExportPort flow tests (#231/#258) — the Tauri invoke boundary is
 * mocked so the collision prompt and the transactional export_run call
 * are asserted as contracts, not side effects.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import { TauriExportPort } from "./tauriPort";
import { createFixtureScoreDocument } from "../score/fixtureDocument";

const invokeMock = vi.fn();
vi.mock("@tauri-apps/api/core", () => ({
  invoke: (...args: unknown[]) => invokeMock(...args),
}));

function source() {
  return {
    doc: createFixtureScoreDocument(),
    basename: "take1",
    audioPath: "C:\\audio\\take.wav",
    audioName: "take.wav",
  };
}

function port() {
  return new TauriExportPort(source);
}

describe("TauriExportPort.export", () => {
  beforeEach(() => {
    invokeMock.mockReset();
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") return [];
      if (cmd === "export_run") {
        return [
          "C:\\out\\take1_source.wav",
          "C:\\out\\take1_concert.musicxml",
        ];
      }
      if (cmd === "detect_tools") {
        return { museScore: { status: "missing" }, ffmpeg: { status: "missing" } };
      }
      throw new Error("unexpected invoke " + cmd);
    });
  });

  it("writes through one transactional export_run call", async () => {
    const res = await port().export({
      formats: ["concertMusicxml", "sourceAudio"],
      destination: "C:\\out",
      basename: "take1",
    });
    const run = invokeMock.mock.calls.find((c) => c[0] === "export_run");
    expect(run).toBeTruthy();
    expect(run?.[1]).toMatchObject({
      dir: "C:\\out",
      audio: { name: "take1_source.wav", src: "C:\\audio\\take.wav" },
      musescorePath: null,
    });
    expect(res.files.map((f) => f.name)).toEqual([
      "take1_concert.musicxml",
      "take1_source.wav",
    ]);
  });

  it("asks onCollision once when names already exist (#231)", async () => {
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") {
        return ["take1_concert.musicxml"];
      }
      if (cmd === "export_run") return ["C:\\out\\take1_concert.musicxml"];
      throw new Error("unexpected " + cmd);
    });
    const seen: string[][] = [];
    await port().export({
      formats: ["concertMusicxml"],
      destination: "C:\\out",
      basename: "take1",
      onCollision: async (names) => {
        seen.push([...names]);
        return "overwrite";
      },
    });
    expect(seen).toEqual([["take1_concert.musicxml"]]);
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(true);
  });

  it("rename re-stems the whole set until the check is clear (#231)", async () => {
    const checks: string[][] = [];
    invokeMock.mockImplementation(async (cmd: string, args: { names?: string[] }) => {
      if (cmd === "export_check_existing") {
        checks.push([...(args.names ?? [])]);
        return args.names?.every((n) => n.startsWith("take1_2_")) ? [] : [args.names?.[0]];
      }
      if (cmd === "export_run") return ["C:\\out\\take1_2_concert.musicxml"];
      throw new Error("unexpected " + cmd);
    });
    const res = await port().export({
      formats: ["concertMusicxml"],
      destination: "C:\\out",
      basename: "take1",
      onCollision: async () => "rename",
    });
    expect(res.files[0].name).toBe("take1_2_concert.musicxml");
    expect(checks.length).toBeGreaterThanOrEqual(2);
  });

  it("cancel surfaces EXPORT_CANCELLED and never runs (#231)", async () => {
    invokeMock.mockImplementation(async (cmd: string) => {
      if (cmd === "export_check_existing") return ["take1_concert.musicxml"];
      if (cmd === "export_run") throw new Error("must not run");
      throw new Error("unexpected " + cmd);
    });
    await expect(
      port().export({
        formats: ["concertMusicxml"],
        destination: "C:\\out",
        basename: "take1",
        onCollision: async () => "cancel",
      }),
    ).rejects.toMatchObject({ code: "EXPORT_CANCELLED" });
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(false);
  });

  it("PDF without MuseScore fails before export_run (#258)", async () => {
    await expect(
      port().export({
        formats: ["concertPdf"],
        destination: "C:\\out",
      }),
    ).rejects.toMatchObject({ code: "MUSESCORE_UNAVAILABLE" });
    expect(invokeMock.mock.calls.some((c) => c[0] === "export_run")).toBe(false);
  });
});

/**
 * TauriExportPort — the real export backend inside the Tauri webview
 * (#99). MusicXML and MIDI are produced entirely client-side from the
 * live score document (user edits included via musicXml(view)); PDF
 * renders through a detected MuseScore install. No engine process is
 * required for any format.
 *
 * Rust commands (src-tauri/src/export.rs) own the privileged halves:
 * folder picking, artifact writes (granted-dir allowlist), tool
 * probing, explorer reveal and the MuseScore subprocess.
 */
import { invoke } from "@tauri-apps/api/core";
import {
  withPathOverride,
  type ToolInfo,
  type ToolPathOverrides,
} from "../diagnostics/types";
import type { ScoreDocumentPort } from "../score/document";
import { buildMidiFile } from "./midi";
import {
  ExportError,
  type ExportCapabilities,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
  type ExportedFile,
} from "./types";

/** ENG-001 filename policy shared with the mock port. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
  // The real artifact keeps the source's own extension — this is only
  // the display-name fallback when the copy result has no file name.
  sourceAudio: "source.wav",
};

/** What the port needs from the app at export time. */
export interface ExportSource {
  /** Live score document (XML bodies + meta); null = nothing to export. */
  readonly doc: ScoreDocumentPort | null;
  /** Default file basename — audio file stem or score title. */
  readonly basename: string;
  /** Absolute path of the loaded audio when it lives on disk — enables
   *  the sourceAudio bundle format (#87). Null for browser-held bytes. */
   readonly audioPath: string | null;
  /** Original audio file name (extension kept) for the bundle copy. */
   readonly audioName: string | null;
}

interface DetectedToolWire {
  status: string;
  path?: string;
}
interface DetectedToolsWire {
  museScore: DetectedToolWire;
  ffmpeg: DetectedToolWire;
}

function toToolInfo(wire: DetectedToolWire): ToolInfo {
  return wire.status === "found"
    ? { status: "found", path: wire.path }
    : { status: "missing" };
}

/** UTF-8-safe base64 (btoa chokes on multibyte; chunk to stay under the
 *  String.fromCharCode arg limit). */
function toBase64(bytes: Uint8Array): string {
  let bin = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

function textToBase64(text: string): string {
  return toBase64(new TextEncoder().encode(text));
}

/** Filesystem-safe basename: strip separators and illegal chars. */
function sanitizeBasename(raw: string): string {
  const cleaned = raw
    .replace(/[\\/:*?"<>|]/g, "_")
    .replace(/\.+$/, "")
    .trim();
  return cleaned || "score";
}

/** Mirror of the Rust-side audio stem sanitize (export_copy_audio):
 *  path/illegal chars AND dots become underscores so the predicted
 *  `<stem>_source.<ext>` name matches what export_run writes. */
function sanitizeAudioStem(raw: string): string {
  const cleaned = raw
    .replace(/[\\/:*?"<>|.]/g, "_")
    .trim();
  return cleaned || "audio";
}

/** Audio file extension (lowercased) for the bundle copy name. */
function audioExtOf(name: string | null): string {
  const m = /\.([A-Za-z0-9]+)$/.exec(name ?? "");
  return m ? m[1].toLowerCase() : "wav";
}

function mapInvokeError(err: unknown): ExportError {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg.includes("PERMISSION_DENIED")) {
    return new ExportError("PERMISSION_DENIED", msg);
  }
  if (msg.includes("MUSESCORE_UNAVAILABLE")) {
    return new ExportError("MUSESCORE_UNAVAILABLE", msg);
  }
  return new ExportError("EXPORT_FAILED", msg);
}

export class TauriExportPort implements ExportPort {
  /** Last tool-path overrides seen by capabilities() — reused by the
   *  PDF branch of export() so a user-specified MuseScore path wins. */
  private overrides?: ToolPathOverrides;

  /** #256: canonical MIDI via the engine's playback_midi_bytes — keeps
   *  velocity / pitch bend / swing / tempo map. When absent (or the
   *  document has no canonical payload) the client-side MusicXML→MIDI
   *  rebuild is used as before. */
  private readonly midiExporter?: (scoreDocument: unknown) => Promise<string>;

  constructor(
    private readonly source: () => ExportSource | null,
    midiExporter?: (scoreDocument: unknown) => Promise<string>,
  ) {
    this.midiExporter = midiExporter;
  }

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    this.overrides = overrides;
    const tools = await invoke<DetectedToolsWire>("detect_tools").catch(
      () => null,
    );
    const museScore = withPathOverride(
      tools ? toToolInfo(tools.museScore) : { status: "missing" },
      overrides?.museScorePath,
    );
    const ffmpeg = withPathOverride(
      tools ? toToolInfo(tools.ffmpeg) : { status: "missing" },
      overrides?.ffmpegPath,
    );
    return {
      // Client-side export needs no engine — report that honestly
      // rather than faking a handshake.
      engineInfo: null,
      protocolVersion: null,
      backend: null,
      museScore,
      ffmpeg,
      audioAvailable: this.source()?.audioPath != null,
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    try {
      return await invoke<string | null>("export_pick_dir", {
        current: current ?? null,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async defaultDestination(): Promise<string> {
    try {
      return await invoke<string>("export_default_dir");
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async export(request: ExportRequest): Promise<ExportResult> {
    const source = this.source();
    if (!source?.doc) {
      throw new ExportError("EXPORT_FAILED", "no score document to export");
    }
    const basename = sanitizeBasename(
      request.basename?.trim() || source.basename || source.doc.meta.title,
    );
    const dir = request.destination;
    const files: ExportedFile[] = [];
    // Plan every artifact up front: names are needed for the
    // collision check (#231) before anything is staged (#258).
    const wantsAudio =
      request.formats.includes("sourceAudio") && source.audioPath != null;
    const pdfFormats = request.formats.filter(
      (f) => f === "concertPdf" || f === "hornPdf",
    );
    const plan = (stem: string) => {
      const names = new Map<ExportFormatId, string>();
      for (const format of request.formats) {
        if (format === "sourceAudio") {
          if (wantsAudio) {
            names.set(
              format,
              `${sanitizeAudioStem(stem)}_source.${audioExtOf(source.audioName)}`,
            );
          }
        } else {
          names.set(format, `${stem}_${ARTIFACT_NAMES[format]}`);
        }
      }
      return names;
    };

    // #231: never overwrite silently — ask once for the whole set.
    let stem = basename;
    let names = plan(stem);
    let existing = await invoke<string[]>("export_check_existing", {
      dir,
      names: [...names.values()],
    }).catch((err) => {
      throw mapInvokeError(err);
    });
    if (existing.length > 0 && request.onCollision) {
      const policy = await request.onCollision(existing);
      if (policy === "cancel") {
        throw new ExportError("EXPORT_CANCELLED", "export cancelled");
      }
      if (policy === "rename") {
        // Re-stem the whole set — every artifact of one export shares
        // one basename, so a suffix keeps the bundle coherent.
        for (let n = 2; n <= 999 && existing.length > 0; n++) {
          stem = `${basename}_${n}`;
          names = plan(stem);
          existing = await invoke<string[]>("export_check_existing", {
            dir,
            names: [...names.values()],
          }).catch((err) => {
            throw mapInvokeError(err);
          });
        }
        if (existing.length > 0) {
          // Pathological: 999 stems taken — refuse rather than
          // silently overwriting after the user chose rename.
          throw new ExportError("EXPORT_FAILED", "no free export name");
        }
      }
    }

    // Resolve MuseScore before staging anything — a missing tool must
    // fail before the transaction, not inside it (#258).
    let museScorePath: string | null = null;
    if (pdfFormats.length > 0) {
      const caps = await this.capabilities(this.overrides);
      museScorePath =
        caps.museScore.status === "found" ? (caps.museScore.path ?? null) : null;
      if (!museScorePath) {
        throw new ExportError(
          "MUSESCORE_UNAVAILABLE",
          "MuseScore not found; PDF export is unavailable",
        );
      }
    }

    // Build payloads: text/binary artifacts go base64; PDFs carry
    // their MusicXML source for the staged render; audio is a path
    // copy (no base64 round-trip for what can be a large file).
    const batch: { name: string; dataBase64: string }[] = [];
    const pdfPayloads: { name: string; musicXml: string }[] = [];
    for (const format of request.formats) {
      const name = names.get(format);
      if (!name) continue;
      if (format === "concertMusicxml") {
        batch.push({ name, dataBase64: textToBase64(source.doc.musicXml("concert")) });
      } else if (format === "hornMusicxml") {
        batch.push({ name, dataBase64: textToBase64(source.doc.musicXml("hornF")) });
      } else if (format === "playbackMidi") {
        // #256: prefer the engine's canonical exporter — it carries
        // velocity / pitch bend / swing / tempo map the MusicXML
        // rebuild loses. Falls back to the client-side build only
        // when no canonical payload or no engine hook exists.
        const canonical = source.doc.canonicalDocument?.();
        if (canonical && this.midiExporter) {
          let midiBase64: string;
          try {
            midiBase64 = await this.midiExporter(canonical);
          } catch (err) {
            const msg = err instanceof Error ? err.message : String(err);
            throw new ExportError("EXPORT_FAILED", msg);
          }
          batch.push({ name, dataBase64: midiBase64 });
        } else {
          batch.push({
            name,
            dataBase64: toBase64(buildMidiFile(source.doc.musicXml("concert"))),
          });
        }
      } else if (format === "concertPdf" || format === "hornPdf") {
        pdfPayloads.push({
          name,
          musicXml: source.doc.musicXml(format === "hornPdf" ? "hornF" : "concert"),
        });
      }
    }

    // #258: one transactional call — audio + files + PDFs are staged
    // and committed together; a failure anywhere writes nothing.
    const paths = await invoke<string[]>("export_run", {
      dir,
      audio: wantsAudio
        ? { name: names.get("sourceAudio"), src: source.audioPath }
        : null,
      files: batch,
      pdfs: pdfPayloads,
      musescorePath: museScorePath,
    }).catch((err) => {
      throw mapInvokeError(err);
    });

    // export_run returns staged-commit order: audio, files, then PDFs —
    // map back onto formats by name for the result list.
    const byName = new Map(paths.map((p) => [p.split(/[\\/]/).pop() ?? "", p]));
    for (const format of request.formats) {
      const name = names.get(format);
      if (!name) continue;
      files.push({
        format,
        name,
        path: byName.get(name) ?? `${dir}\\${name}`,
      });
    }
    return { destination: dir, files };
  }

  async revealInExplorer(path: string): Promise<boolean> {
    try {
      await invoke("reveal_in_explorer", { path });
      return true;
    } catch {
      return false;
    }
  }

  /** §13 高度編集: hand the live score to the MuseScore GUI. The view
   *  argument picks concert vs F管 written pitch — the same document the
   *  user is looking at, edits included. */
  async openInMuseScore(
    view: "concert" | "hornF",
    overrides?: ToolPathOverrides,
  ): Promise<string> {
    const source = this.source();
    if (!source?.doc) {
      throw new ExportError("EXPORT_FAILED", "no score document to open");
    }
    const caps = await this.capabilities(overrides ?? this.overrides);
    const exe = caps.museScore.status === "found" ? caps.museScore.path : null;
    if (!exe) {
      throw new ExportError(
        "MUSESCORE_UNAVAILABLE",
        "MuseScore not found; set its path in 設定 → ツール",
      );
    }
    try {
      return await invoke<string>("open_in_musescore", {
        musescorePath: exe,
        musicXml: source.doc.musicXml(view),
        basename: source.basename || source.doc.meta.title,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }
}

/**
 * Export contract types (UI-060; GUI_UX_SPEC §17; ENG-001 semantics).
 *
 * The dialog talks to a typed {@link ExportPort} (port.ts) — the same
 * port/gate layering the sidecar client uses (`src/sidecar/port.ts` in
 * UI-040): a mock port makes the whole UX exercisable in a plain browser,
 * while a real engine reports the same capability surface through the
 * `engine.handshake` response once the spawn bridge lands.
 */

import type {
  EngineInfo,
  ToolInfo,
  ToolPathOverrides,
} from "../diagnostics/types";

/**
 * The five export choices of §17. ENG-001 semantics:
 * - `concertMusicxml` / `hornMusicxml` → `*_concert.musicxml` /
 *   `*_horn_in_f.musicxml`; the F管ホルン artifact carries written pitches
 *   plus the -P5 `<transpose>` element so readers recover sounding pitch;
 * - `playbackMidi` → `*_playback.mid`, always *sounding* (concert) pitch —
 *   SMF has no transposing-instrument semantics, so a written-pitch MIDI
 *   would be ambiguous about its own pitch space (再生用MIDIは実音);
 * - `concertPdf` / `hornPdf` → rendered through MuseScore, hence gated by
 *   the MuseScore tool capability.
 * - `sourceAudio` → the original audio file copied alongside the score
 *   artifacts (#87 成果物同梱): a recording→score bundle stays usable
 *   outside the app. Gated by `capabilities.audioAvailable` — only refs
 *   backed by a real path can be copied.
 */
export type ExportFormatId =
  | "concertMusicxml"
  | "hornMusicxml"
  | "concertPdf"
  | "hornPdf"
  | "playbackMidi"
  | "sourceAudio";

/** Checkbox grouping from the spec mock-up (楽譜 / PDF / MIDI / 音声). */
export type ExportFormatGroup = "score" | "pdf" | "midi" | "audio";

export const EXPORT_FORMAT_GROUPS: Record<ExportFormatId, ExportFormatGroup> = {
  concertMusicxml: "score",
  hornMusicxml: "score",
  concertPdf: "pdf",
  hornPdf: "pdf",
  playbackMidi: "midi",
  sourceAudio: "audio",
};

export const EXPORT_FORMAT_IDS: readonly ExportFormatId[] = [
  "concertMusicxml",
  "hornMusicxml",
  "concertPdf",
  "hornPdf",
  "playbackMidi",
  "sourceAudio",
];

/**
 * The capability surface the export dialog needs — a subset of the engine
 * handshake plus local tool detection (MuseScore drives PDF availability;
 * FFmpeg is reported for consistency with diagnostics).
 */
export interface ExportCapabilities {
  readonly engineInfo: EngineInfo | null;
  readonly protocolVersion: number | null;
  /** Transcription backend id when known (diagnostics parity). */
  readonly backend: string | null;
  readonly museScore: ToolInfo;
  readonly ffmpeg: ToolInfo;
  /** True when the loaded audio is backed by a real path and can be
   *  copied into the export bundle (sourceAudio format, #87). */
  readonly audioAvailable: boolean;
}

/** PDF export requires MuseScore; everything else stays available (§17). */
export function pdfBlocked(capabilities: ExportCapabilities): boolean {
  return capabilities.museScore.status !== "found";
}

/** A single written artifact returned by a successful export. */
export interface ExportedFile {
  readonly format: ExportFormatId;
  /** Absolute path of the written file. */
  readonly path: string;
  /** File name only (for display). */
  readonly name: string;
}

export interface ExportRequest {
  /** Formats to write — at least one, all enabled by capabilities. */
  readonly formats: readonly ExportFormatId[];
  /** Destination directory (absolute path). */
  readonly destination: string;
  /** Document base name for `<basename>_<artifact>` naming (ENG-001). */
  readonly basename?: string;
  /** #231: called once before writing when target names already
   *  exist — the host decides the collision policy for the whole set.
   *  "rename" re-stems every artifact to <basename>_N; "cancel"
   *  aborts the export with an EXPORT_CANCELLED result-free rejection.
   *  Absent = overwrite (non-interactive ports, tests). */
  readonly onCollision?: (
    existingNames: readonly string[],
  ) => Promise<"overwrite" | "rename" | "cancel">;
}

export interface ExportResult {
  readonly destination: string;
  readonly files: readonly ExportedFile[];
}

/**
 * Stable error codes the UI maps onto Japanese recovery copy — raw engine
 * messages and stack traces never reach the dialog (§20, acceptance:
 * "technical stack trace is not shown in normal error UI").
 */
export type ExportErrorCode =
  /** Destination is not writable (permission / read-only). */
  | "PERMISSION_DENIED"
  /** No engine connected (sidecar not spawned / crashed). */
  | "ENGINE_UNAVAILABLE"
  /** PDF was requested without a usable MuseScore. */
  | "MUSESCORE_UNAVAILABLE"
  /** Anything else — generic failure with retry/choose-destination. */
  | "EXPORT_FAILED"
  /** #231: the user cancelled at the collision prompt — resolved
   *  quietly, not an error surface. */
  | "EXPORT_CANCELLED";

export class ExportError extends Error {
  readonly code: ExportErrorCode;
  constructor(code: ExportErrorCode, message: string) {
    super(message);
    this.name = "ExportError";
    this.code = code;
  }
}

/** Maps an unknown thrown value to a stable code for the dialog. */
export function exportErrorCode(err: unknown): ExportErrorCode {
  if (err instanceof ExportError) return err.code;
  return "EXPORT_FAILED";
}

/**
 * ExportPort — the seam between the 書き出し dialog and a concrete export
 * backend (see port.ts for the runtime gate). Declared here with the rest
 * of the contract so implementations never import the port module itself.
 */
export interface ExportPort {
  /**
   * Probe export-relevant capabilities: engine identity, protocol version,
   * backend and tool detection. `overrides` carries the user-specified tool
   * paths from 設定 → ツール/書き出し (non-empty paths win over probing).
   * Rejects with ExportError(ENGINE_UNAVAILABLE) when no engine/backend
   * can answer — the dialog shows the recovery surface, not a crash.
   */
  capabilities(overrides?: ToolPathOverrides): Promise<ExportCapabilities>;
  /**
   * Ask the user for a destination directory (native picker where a real
   * bridge exists). Resolves null when the picker was cancelled.
   */
  chooseDestination(current?: string): Promise<string | null>;
  /**
   * The directory preselected in the dialog: the 設定 → 書き出し default
   * when set, else the engine/OS documents location.
   */
  defaultDestination(): Promise<string>;
  /**
   * Run the export. Resolves with the written artifacts; rejects with a
   * typed {@link ExportError} whose code drives the §20 recovery surface —
   * raw engine output/stack traces stay behind the port.
   */
  export(request: ExportRequest): Promise<ExportResult>;
  /**
   * Reveal a directory in the OS file manager (エクスプローラーで表示).
   * Resolves false where the bridge cannot do that — the caller announces
   * the failure instead of pretending.
   */
  revealInExplorer(path: string): Promise<boolean>;
  /**
   * §13 高度編集: open the live score (user edits included) in the
   * MuseScore GUI — stages the current view's MusicXML to a temp file
   * and launches the detected/user-pinned executable. Resolves the
   * staged path; rejects with ExportError(MUSESCORE_UNAVAILABLE) when
   * no MuseScore is usable. Optional so browser/mock ports and leaner
   * test doubles keep compiling — an absent implementation is a no-op.
   */
  openInMuseScore?(
    view: "concert" | "hornF",
    overrides?: ToolPathOverrides,
  ): Promise<string>;
}
